import subprocess,re
bins={k:f'/out-{k}/compress_frame_fuzzer' for k in ('vul','fix')}
def syms(p):
 out=subprocess.check_output(['nm','-S','--size-sort',p],text=True,errors='replace')
 d={}
 for line in out.splitlines():
  m=re.match(r'^([0-9a-f]+)\s+([0-9a-f]+)\s+([tTwW])\s+(.+)$',line)
  if m: d[m.group(4)]=(int(m.group(1),16),int(m.group(2),16),m.group(3))
 return d
v,f=map(syms,bins.values())
print('=== changed text symbol sizes ===')
rows=[]
for n in v.keys()&f.keys():
 if v[n][1]!=f[n][1]: rows.append((abs(f[n][1]-v[n][1]),n,v[n],f[n]))
for _,n,a,b in sorted(rows,reverse=True):
 print(f'{n:55} vul={a[0]:#x}/{a[1]:#x} fix={b[0]:#x}/{b[1]:#x} sizedelta={b[1]-a[1]:+#x}')
print('\n=== fixed-only text symbols ===')
for n in sorted(f.keys()-v.keys(), key=lambda n:f[n][0]): print(f'{f[n][0]:#x}/{f[n][1]:#x} {n}')
print('\n=== vulnerable-only text symbols ===')
for n in sorted(v.keys()-f.keys(), key=lambda n:v[n][0]): print(f'{v[n][0]:#x}/{v[n][1]:#x} {n}')
print('\n=== relevant symbol map ===')
for n in sorted(v, key=lambda n:v[n][0]):
 if any(x in n.lower() for x in ('frame','schunk','msgpack','free','decompress')) and v[n][0]<0x42c000:
  print(f'{v[n][0]:#x}/{v[n][1]:#x} {n}')
PY
printf '\n--- fixed diagnostic source references ---\n'
for s in 'Pointer is NULL' 'Invalid or unsupported compressed stream token'; do
 echo "[$s]"
 off=$(strings -a -t x /out-fix/compress_frame_fuzzer | awk -v q="$s" 'index($0,q){print $1;exit}')
 echo fileoff=0x$off
 # executable is flat first RX segment, so VA=0x400000+off
 va=$(printf '0x%x' $((0x400000+0x$off)))
 echo va=$va
 r2 -2qc "aaa; axt @$va" /out-fix/compress_frame_fuzzer 2>/dev/null | head -40
done"}

